/* Question bank derived from the 2026-2027 Oregon Driver Manual.
   Types: mc (multiple choice), tf (true/false), yn (yes/no),
          fib (fill in the blank), multi (choose all that apply),
          sign (identify the SVG sign).
   For mc/sign: a = index of correct option.
   For tf/yn:   a = true or false.
   For fib:     a = array of accepted answers (case-insensitive).
   For multi:   a = array of correct option indices. */
const CATEGORIES = {
  signs:   { name: "Signs & Traffic Signals", icon: "🚦" },
  rules:   { name: "Rules of the Road", icon: "🛣️" },
  speed:   { name: "Speed & the Basic Rule", icon: "⏱️" },
  parking: { name: "Parking, Stopping & School Zones", icon: "🅿️" },
  safe:    { name: "Safe & Defensive Driving", icon: "🛡️" },
  impaired:{ name: "Impaired & Distracted Driving", icon: "🚫" },
  license: { name: "Licensing, Insurance & Collisions", icon: "🪪" },
  sharing: { name: "Sharing the Road", icon: "🚲" }
};

